local diff_utils = require("utils.diff")

local M = {}

M.defaults = {
  auto_separator = true,
}

M.config = vim.deepcopy(M.defaults)

--- Split a markdown table row into trimmed cell contents and indentation
---@param line string
---@return string[] cells, string indent
function M.split_row(line)
  local parts = {}
  local start = 1
  while true do
    local s, e = line:find("|", start, true)
    if not s then
      table.insert(parts, line:sub(start))
      break
    end
    table.insert(parts, line:sub(start, s - 1))
    start = e + 1
  end

  local has_leading_pipe = #parts >= 2 and parts[1]:match("^%s*$") ~= nil
  local has_trailing_pipe = #parts >= 2 and parts[#parts]:match("^%s*$") ~= nil

  local start_idx = has_leading_pipe and 2 or 1
  local end_idx = has_trailing_pipe and (#parts - 1) or #parts

  local cells = {}
  for i = start_idx, end_idx do
    local content = parts[i]:match("^%s*(.-)%s*$") or ""
    table.insert(cells, content)
  end

  local indent = line:match("^(%s*)") or ""
  return cells, indent
end

--- Check if a list of cells constitutes a markdown table separator row (e.g. `| --- | :---: | ---: |`)
---@param cells string[]
---@return boolean
function M.is_separator_row(cells)
  if #cells == 0 then
    return false
  end
  for _, cell in ipairs(cells) do
    if not cell:match("^:?%-+:?$") then
      return false
    end
  end
  return true
end

--- Determine column alignment from a separator cell
---@param cell string
---@return "center" | "right" | "left_colon" | "left"
function M.get_column_alignment(cell)
  if cell:match("^:%-+:$") then
    return "center"
  elseif cell:match("^%-+:$") then
    return "right"
  elseif cell:match("^:%-+$") then
    return "left_colon"
  else
    return "left"
  end
end

--- Format a separator cell according to alignment and width (matching Prettier standards)
---@param align_type "center" | "right" | "left_colon" | "left"
---@param width integer
---@return string
function M.format_separator_cell(align_type, width)
  width = math.max(width, 3)
  if align_type == "center" then
    local dashes = width - 2
    if dashes < 1 then
      dashes = 1
    end
    return ":" .. string.rep("-", dashes) .. ":"
  elseif align_type == "right" then
    local dashes = width - 1
    if dashes < 2 then
      dashes = 2
    end
    return string.rep("-", dashes) .. ":"
  elseif align_type == "left_colon" then
    local dashes = width - 1
    if dashes < 2 then
      dashes = 2
    end
    return ":" .. string.rep("-", dashes)
  else
    return string.rep("-", width)
  end
end

--- Format a table cell's text according to column alignment and target width
---@param text string
---@param align_type "center" | "right" | "left_colon" | "left"
---@param width integer
---@return string
function M.format_cell(text, align_type, width)
  local cur_w = vim.fn.strdisplaywidth(text)
  local diff = width - cur_w
  if diff <= 0 then
    return text
  end

  if align_type == "right" then
    return string.rep(" ", diff) .. text
  elseif align_type == "center" then
    local left_pad = math.floor(diff / 2)
    local right_pad = diff - left_pad
    return string.rep(" ", left_pad) .. text .. string.rep(" ", right_pad)
  else
    return text .. string.rep(" ", diff)
  end
end

--- Format an array of markdown table lines
---@param lines string[]
---@param opts? { separator?: boolean }
---@return string[]
function M.format_table(lines, opts)
  opts = opts or {}
  local auto_separator = (opts.separator ~= false)
  if opts.separator == nil then
    auto_separator = M.config.auto_separator
  end

  local table_rows = {}
  local min_indent = nil

  for _, line in ipairs(lines) do
    if line:find("|") then
      local cells, indent = M.split_row(line)
      table.insert(table_rows, { raw = line, cells = cells, indent = indent })
      local indent_len = #indent
      if min_indent == nil or indent_len < min_indent then
        min_indent = indent_len
      end
    end
  end

  if #table_rows == 0 then
    return lines
  end

  min_indent = min_indent or 0
  local base_indent = string.rep(" ", min_indent)

  -- Check if row 2 is an existing separator row
  local has_separator = false
  local sep_row_idx = nil
  if #table_rows >= 2 and M.is_separator_row(table_rows[2].cells) then
    has_separator = true
    sep_row_idx = 2
  end

  -- Determine number of columns
  local num_cols = 0
  for _, row in ipairs(table_rows) do
    if #row.cells > num_cols then
      num_cols = #row.cells
    end
  end

  -- If no separator row and auto_separator is enabled, insert a default separator row at index 2
  if not has_separator and auto_separator and #table_rows >= 1 then
    local sep_cells = {}
    for _ = 1, num_cols do
      table.insert(sep_cells, "---")
    end
    table.insert(table_rows, 2, { raw = "", cells = sep_cells, indent = base_indent, is_generated_sep = true })
    has_separator = true
    sep_row_idx = 2
  end

  -- Determine per-column alignment from separator row
  local col_alignments = {}
  if has_separator and sep_row_idx then
    for c = 1, num_cols do
      local sep_cell = table_rows[sep_row_idx].cells[c] or "---"
      col_alignments[c] = M.get_column_alignment(sep_cell)
    end
  else
    for c = 1, num_cols do
      col_alignments[c] = "left"
    end
  end

  -- Compute column widths (excluding separator row characters)
  local col_widths = {}
  for c = 1, num_cols do
    col_widths[c] = 3
  end

  for r, row in ipairs(table_rows) do
    if not (has_separator and r == sep_row_idx) then
      for c = 1, num_cols do
        local cell_text = row.cells[c] or ""
        local w = vim.fn.strdisplaywidth(cell_text)
        if w > col_widths[c] then
          col_widths[c] = w
        end
      end
    end
  end

  -- Build formatted lines
  local result = {}
  for r, row in ipairs(table_rows) do
    local formatted_cells = {}
    if has_separator and r == sep_row_idx then
      for c = 1, num_cols do
        local sep = M.format_separator_cell(col_alignments[c], col_widths[c])
        table.insert(formatted_cells, sep)
      end
    else
      for c = 1, num_cols do
        local cell_text = row.cells[c] or ""
        local formatted = M.format_cell(cell_text, col_alignments[c], col_widths[c])
        table.insert(formatted_cells, formatted)
      end
    end
    local line_out = base_indent .. "| " .. table.concat(formatted_cells, " | ") .. " |"
    table.insert(result, line_out)
  end

  return result
end

--- Expand a line to the contiguous table block containing `|`
---@param bufnr integer
---@param line integer 1-indexed line
---@return integer start_line, integer end_line
function M.find_table_range(bufnr, line)
  local total_lines = vim.api.nvim_buf_line_count(bufnr)
  local start_l = line
  local end_l = line

  local cur_line = vim.api.nvim_buf_get_lines(bufnr, line - 1, line, false)[1] or ""
  if not cur_line:find("|") then
    return line, line
  end

  while start_l > 1 do
    local prev = vim.api.nvim_buf_get_lines(bufnr, start_l - 2, start_l - 1, false)[1] or ""
    if prev:find("|") and not prev:match("^%s*$") then
      start_l = start_l - 1
    else
      break
    end
  end

  while end_l < total_lines do
    local next_l = vim.api.nvim_buf_get_lines(bufnr, end_l, end_l + 1, false)[1] or ""
    if next_l:find("|") and not next_l:match("^%s*$") then
      end_l = end_l + 1
    else
      break
    end
  end

  return start_l, end_l
end

--- Format table in buffer between start_line and end_line
---@param bufnr integer
---@param start_line integer 1-indexed line
---@param end_line integer 1-indexed line
---@param opts? table
---@return boolean
function M.align_table_range(bufnr, start_line, end_line, opts)
  bufnr = bufnr == 0 and vim.api.nvim_get_current_buf() or bufnr
  opts = opts or {}

  if start_line == end_line then
    start_line, end_line = M.find_table_range(bufnr, start_line)
  end

  local old_lines = vim.api.nvim_buf_get_lines(bufnr, start_line - 1, end_line, false)
  if #old_lines == 0 then
    return false
  end

  local new_lines = M.format_table(old_lines, opts)
  return diff_utils.apply_diff(bufnr, start_line - 1, old_lines, new_lines, { save_view = true })
end

--- Format table under cursor or in visual selection
--- Can be called directly from Lua keymaps in Normal or Visual mode
---@param opts? table
---@return boolean
function M.format(opts)
  local mode = vim.fn.mode()
  local bufnr = vim.api.nvim_get_current_buf()
  local start_line, end_line

  if mode:match("[vV\22]") then
    local esc = vim.api.nvim_replace_termcodes("<Esc>", true, false, true)
    vim.api.nvim_feedkeys(esc, "nx", false)
    start_line = vim.api.nvim_buf_get_mark(bufnr, "<")[1]
    end_line = vim.api.nvim_buf_get_mark(bufnr, ">")[1]
  else
    local line = vim.api.nvim_win_get_cursor(0)[1]
    start_line, end_line = line, line
  end

  if start_line == 0 or end_line == 0 then
    return false
  end
  if start_line > end_line then
    start_line, end_line = end_line, start_line
  end

  return M.align_table_range(bufnr, start_line, end_line, opts)
end

--- Parse command arguments
---@param args_str? string
---@return { separator?: boolean }
function M.parse_args(args_str)
  local opts = {}
  if not args_str or args_str:match("^%s*$") then
    return opts
  end

  for tok in args_str:gmatch("%S+") do
    local lower = tok:lower()
    if lower == "separator=false" then
      opts.separator = false
    elseif lower == "separator=true" then
      opts.separator = true
    end
  end
  return opts
end

--- Autocompletion handler for :Table command
---@param arg_lead string
---@return string[]
function M.complete(arg_lead)
  local candidates = { "separator=false", "format" }
  local matches = {}
  for _, c in ipairs(candidates) do
    if vim.startswith(c, arg_lead) then
      table.insert(matches, c)
    end
  end
  return matches
end

--- Setup markdown table command
---@param opts? { auto_separator?: boolean }
function M.setup(opts)
  M.config = vim.tbl_deep_extend("force", M.defaults, opts or {})

  vim.api.nvim_create_user_command("Table", function(cmd_opts)
    local bufnr = vim.api.nvim_get_current_buf()
    local parsed = M.parse_args(cmd_opts.args)
    M.align_table_range(bufnr, cmd_opts.line1, cmd_opts.line2, parsed)
  end, {
    range = true,
    nargs = "*",
    complete = M.complete,
    desc = "Markdown table formatter",
  })
end

return M
